/** `https://lrc.red/s/<ISRC>.song.json`. Only the fields used here; the file carries more. */
export interface LRCRedSong {
	id: string;
	title?: string;
	artist?: string;
	album?: string;
	/** Seconds. */
	duration?: number;
	/** `word`, `line`, … */
	level?: string;
	language?: string;
	songwriters?: string[];
	/** True when the timing was generated by a model rather than synced by a person. */
	byModel?: boolean;
	/** The same TTML as `<ISRC>.ttml`. */
	source?: string;
}
